// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.base.SailDataset;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** Deterministic source-work evidence for the context counts generated by Workbench Clear and Graphs pages. */
class LmdbContextCountAccessTest {

	@TempDir
	Path directory;

	@ParameterizedTest(name = "single-plane context count, adjacency={0}")
	@ValueSource(booleans = { false, true })
	void soleExplicitPlaneContextCountsDoNotReadEachStatement(boolean adjacency) throws Exception {
		Map<String, Long> small = countContext("small", 8, adjacency);
		Map<String, Long> large = countContext("large", 1024, adjacency);
		assertThat(large.getOrDefault("mdb_cursor_get", 0L))
				.as("context-only size must use authoritative metadata when the other statement plane is empty; "
						+ "native cursor reads must not grow with statement count: small=%s, large=%s", small, large)
				.isEqualTo(small.getOrDefault("mdb_cursor_get", 0L));
		assertThat(large.getOrDefault("adjacencyLookupHits", 0L))
				.as("an authoritative context metadata count must not sweep adjacency statement payloads: %s", large)
				.isZero();
	}

	@ParameterizedTest(name = "context metadata guards and snapshots, adjacency={0}")
	@ValueSource(booleans = { false, true })
	void metadataCountsPreservePlanesPromotionContextsAndTransactions(boolean adjacency) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("semantics").toFile(),
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(adjacency));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			var values = repository.getValueFactory();
			IRI graph = values.createIRI("urn:count:graph");
			Resource blankGraph = values.createBNode("graph");
			IRI predicate = values.createIRI("urn:count:p");
			IRI first = values.createIRI("urn:count:first");
			IRI second = values.createIRI("urn:count:second");
			try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
				connection.begin();
				connection.addInferredStatement(first, predicate, first, graph);
				connection.addInferredStatement(second, predicate, second, graph);
				connection.addInferredStatement(first, predicate, first, (Resource) null);
				connection.commit();
			}
			assertPlaneCounts(store, graph, 0, 2);
			assertPlaneCounts(store, null, 0, 1);
			try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
				connection.begin();
				// Promotion moves one quad between planes without increasing the combined context count.
				connection.addStatement(first, predicate, first, graph);
				connection.addStatement(first, predicate, first, blankGraph);
				connection.commit();
			}
			assertPlaneCounts(store, graph, 1, 1);
			assertPlaneCounts(store, blankGraph, 1, 0);
			assertPlaneCounts(store, predicate, 0, 0);
			try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
				connection.begin();
				connection.removeInferredStatement(second, predicate, second, graph);
				connection.removeInferredStatement(first, predicate, first, (Resource) null);
				connection.commit();
			}
			assertPlaneCounts(store, graph, 1, 0);
			assertPlaneCounts(store, null, 0, 0);
			try (var reader = repository.getConnection(); var writer = repository.getConnection()) {
				// SNAPSHOT additionally excludes phantom additions between separate reads; SNAPSHOT_READ only
				// guarantees consistency within each individual read operation.
				reader.begin(IsolationLevels.SNAPSHOT);
				assertThat(reader.size(graph)).isEqualTo(1);
				writer.add(second, predicate, second, graph);
				assertThat(reader.size(graph)).as("context and plane metadata belong to the same read snapshot")
						.isEqualTo(1);
				reader.commit();
				assertThat(reader.size(graph)).isEqualTo(2);
				writer.begin();
				writer.add(values.createIRI("urn:count:rolled-back"), predicate, first, graph);
				assertThat(writer.size(graph)).as("uncommitted additions remain visible to their own transaction")
						.isEqualTo(3);
				writer.rollback();
				assertThat(writer.size(graph)).isEqualTo(2);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void assertPlaneCounts(LmdbStore store, Resource graph, long explicit, long inferred) {
		try (SailDataset explicitData = store.getBackingStore()
				.getExplicitSailSource()
				.dataset(IsolationLevels.SNAPSHOT_READ);
				SailDataset inferredData = store.getBackingStore()
						.getInferredSailSource()
						.dataset(IsolationLevels.SNAPSHOT_READ)) {
			assertThat(explicitData.getStatementCount(null, null, null, graph)).as("explicit %s", graph)
					.isEqualTo(explicit);
			assertThat(inferredData.getStatementCount(null, null, null, graph)).as("inferred %s", graph)
					.isEqualTo(inferred);
		}
	}

	private Map<String, Long> countContext(String name, int count, boolean adjacency) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve(name).toFile(),
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(adjacency));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			IRI graph = repository.getValueFactory().createIRI("urn:count:graph");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				connection.begin();
				for (int index = 0; index < count; index++) {
					connection.add(values.createIRI("urn:count:subject:" + index), values.createIRI("urn:count:p"),
							values.createLiteral(index), graph);
				}
				connection.commit();
			}
			if (adjacency) {
				assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS))
						.as(store.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}
			try (var connection = repository.getConnection();
					LmdbStartupReadCounter reads = new LmdbStartupReadCounter()) {
				long adjacencyBefore = adjacency
						? store.getBackingStore().directAdjacencyStore().snapshotMetrics().lookupHits
						: 0L;
				assertThat(connection.size(graph)).isEqualTo(count);
				Map<String, Long> operations = new LinkedHashMap<>(reads.operations());
				if (adjacency) {
					operations.put("adjacencyLookupHits",
							store.getBackingStore().directAdjacencyStore().snapshotMetrics().lookupHits
									- adjacencyBefore);
				}
				System.out.println("Context-count source work: adjacency=" + adjacency + ", statements=" + count
						+ ", operations=" + operations);
				return operations;
			}
		} finally {
			repository.shutDown();
		}
	}
}
